import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col } from "reactstrap";
import "../Styles/Register.css";

const INDUSTRIES = [
  "Technology",
  "Education",
  "Hospitality",
  "Retail / Store",
  "Logistics",
  "Government Services",
  "Other",
];

const LOCATIONS = ["Salalah", "Mughsail", "Taqah", "Mirbat", "Other"];

const Register = () => {
  const [role, setRole] = useState("company");

  const [companyName, setCompanyName] = useState("");
  const [email, setEmail] = useState("");
  const [industry, setIndustry] = useState(INDUSTRIES[0]);
  const [location, setLocation] = useState(LOCATIONS[0]);
  const [password, setPassword] = useState("");

  const [entityType, setEntityType] = useState("Private");
  const [training, setTraining] = useState(false);
  const [foundedDate, setFoundedDate] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    const payload = {
      companyName,
      email,
      password,
      industry,
      location,
      entityType,
      training,
      foundedDate,
    };
    console.log(payload);
    alert("Company Registered (Mock) ✅");
  };

  return (
    <div className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>

      <p className="reg-sub">
        Please Choose your role to continue and fill in the following:
      </p>

      {/* Switch */}
      <div className="role-switch">
        <button
          className={role === "student" ? "role-btn active" : "role-btn"}
          onClick={() => setRole("student")}
        >
          Student
        </button>
        <button
          className={role === "company" ? "role-btn active" : "role-btn"}
          onClick={() => setRole("company")}
        >
          Company
        </button>
      </div>

      <div className="reg-card">
        <Form onSubmit={handleSubmit}>
          {/* Company Name */}
          <FormGroup>
            <Label>Company Name</Label>
            <Input
              type="text"
              placeholder="Dhofar Company ..."
              value={companyName}
              onChange={(e) => setCompanyName(e.target.value)}
              required
            />
          </FormGroup>

          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Email</Label>
                <Input
                  type="email"
                  placeholder="you@example.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>

            <Col md={6}>
              <FormGroup>
                <Label>Password</Label>
                <Input
                  type="password"
                  placeholder="**********"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          {/* Dropdowns */}
          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Industry Type</Label>
                <Input
                  type="select"
                  value={industry}
                  onChange={(e) => setIndustry(e.target.value)}
                >
                  {INDUSTRIES.map((i) => (
                    <option key={i}>{i}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>

            <Col md={6}>
              <FormGroup>
                <Label>Location</Label>
                <Input
                  type="select"
                  value={location}
                  onChange={(e) => setLocation(e.target.value)}
                >
                  {LOCATIONS.map((l) => (
                    <option key={l}>{l}</option>
                  ))}
                </Input>
              </FormGroup>
            </Col>
          </Row>

          {/* Entity Radio */}
          <div className="entity-box">
            <Label>Entity Type</Label>
            <div className="entity-options">
              <label>
                <Input
                  type="radio"
                  value="Private"
                  checked={entityType === "Private"}
                  onChange={(e) => setEntityType(e.target.value)}
                />{" "}
                Private
              </label>
              <label>
                <Input
                  type="radio"
                  value="Government"
                  checked={entityType === "Government"}
                  onChange={(e) => setEntityType(e.target.value)}
                />{" "}
                Government / Ministry
              </label>
              <label>
                <Input
                  type="radio"
                  value="SmallBusiness"
                  checked={entityType === "SmallBusiness"}
                  onChange={(e) => setEntityType(e.target.value)}
                />{" "}
                Small Business
              </label>
            </div>
          </div>

          {/* Checkbox */}
          <FormGroup check className="training-box">
            <Input
              type="checkbox"
              checked={training}
              onChange={(e) => setTraining(e.target.checked)}
            />
            <Label check>Provide training for newcomers</Label>
          </FormGroup>

          {/* Date Picker */}
          <FormGroup>
            <Label>Founded Date</Label>
            <Input
              type="date"
              value={foundedDate}
              onChange={(e) => setFoundedDate(e.target.value)}
            />
          </FormGroup>

          <button className="reg-btn">Sign up</button>

          <p className="login-text">
            Already have an account? <span>Log in now!</span>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default Register;
